          "e": "การตรวจสอบการเงิน (Financial Audit) มุ่งตรวจความถูกต้องครบถ้วนของรายงานการเงิน ต่างจาก Compliance Audit (ตรวจการปฏิบัติตามกฎหมาย) และ Performance Audit (ตรวจความคุ้มค่า/ประสิทธิภาพ)",
