          "a": 1,
          "e": "การตรวจสอบการปฏิบัติตามกฎหมาย (Compliance Audit) มุ่งตรวจว่าการใช้จ่ายเงินและการดำเนินงานเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ และมติที่เกี่ยวข้องหรือไม่",
