            "ไม่ต่ำกว่า 40 ปี ไม่เกิน 70 ปี",
            "ไม่ต่ำกว่า 45 ปี ไม่เกิน 70 ปี",
            "ไม่ต่ำกว่า 50 ปี ไม่เกิน 75 ปี"
