          "a": 1,
          "e": "คตง. เป็นผู้สรรหาและคัดเลือกผู้ว่าการฯ แล้วเสนอวุฒิสภาให้ความเห็นชอบ — ต้องแยกผู้สรรหาออกจากผู้ให้ความเห็นชอบ",
