          "a": 0,
          "e": "กรณีพบการกระทำที่อาจเป็นการทุจริต ให้แจ้งคณะกรรมการ ป.ป.ช. ส่วนความผิดอาญาอื่นแจ้งหน่วยงานที่เกี่ยวข้อง",
          "id": "sao-1-1345c608ae0f",
