          "a": 1,
          "e": "หลักทั่วไปตรวจผลสัมฤทธิ์เมื่อดำเนินการเสร็จ แต่กรณีเห็นชัดว่าจะไม่เกิดผลสัมฤทธิ์หรือขาดประสิทธิภาพ แจ้งพร้อมคำแนะนำก่อนได้ หากหน่วยรับตรวจมีเหตุผลคัดค้านให้ร่วมกันหารือหาข้อยุติ",
