          "e": "20% ของ 3.6 เท่ากับ 0.72 แต่รายจ่ายลงทุนต้องไม่น้อยกว่าส่วนขาดดุล 0.80 ด้วย จึงใช้ค่าที่สูงกว่า ไม่ใช่ดูเงื่อนไขร้อยละอย่างเดียว",
