          "q": "เจ้าหน้าที่ได้รับข้อเสนอให้ญาติใช้สถานที่พักฟรีจากผู้รับตรวจ แลกกับการละเว้นข้อสังเกต แม้เจ้าหน้าที่ไม่ได้พักเองควรพิจารณาอย่างไร",
